// Adaptive Sorting Algorithm Implementation
// This program implements a sorting algorithm that can be evolved to adapt to different data patterns

// HYPOTHESIS-1: Removing the reverse-sorted check (which was REFUTED) and keeping only the is_sorted guard with inline(always) will improve performance_score above the current 0.9997
// MECHANISM-1: The reverse check added an extra O(n) scan on most inputs hurting perf; inline(always) forces inlining even in benchmarks where inline hint may be ignored
// EXPECT-1: performance_score > 0.9997
// RESULT-1: REFUTED (actual=0.9996607421349594)
// HYPOTHESIS-2: Using is_sorted() method instead of windows(2).all() provides cleaner code and potentially faster compiled output
// MECHANISM-2: is_sorted() is a dedicated stdlib method that may have specialized optimizations vs the generic windows iterator approach
// EXPECT-2: combined_score > 0.9998
// RESULT-2: REFUTED (actual=0.9997814065305639)
// HYPOTHESIS-3: A minimal function with just len check plus sort_unstable and inline(always) avoids the O(n) pre-scan overhead on unsorted data while keeping optimal stdlib performance
// MECHANISM-3: The sorted pre-check costs O(n) on unsorted data for no benefit; pdqsort already detects sorted runs internally; inline(always) eliminates call overhead
// EXPECT-3: performance_score > 0.9997
// RESULT-3: REFUTED (actual=0.9996607421349594)
#[inline(always)]
pub fn adaptive_sort<T: Ord>(arr: &mut [T]) {
    if arr.len() > 1 { arr.sort_unstable(); }
}
// EVOLVE-BLOCK-END

// Benchmark function to test the sort implementation
pub fn run_benchmark(test_data: Vec<Vec<i32>>) -> BenchmarkResults {
    let mut results = BenchmarkResults {
        times: Vec::new(),
        correctness: Vec::new(),
        adaptability_score: 0.0,
    };

    for data in test_data {
        let mut arr = data.clone();
        let start = std::time::Instant::now();

        adaptive_sort(&mut arr);

        let elapsed = start.elapsed();
        results.times.push(elapsed.as_secs_f64());

        // Check if correctly sorted
        let is_sorted = arr.windows(2).all(|w| w[0] <= w[1]);
        results.correctness.push(is_sorted);
    }

    // Calculate adaptability score based on performance variance
    if results.times.len() > 1 {
        let mean_time: f64 = results.times.iter().sum::<f64>() / results.times.len() as f64;
        let variance: f64 = results.times.iter()
            .map(|t| (t - mean_time).powi(2))
            .sum::<f64>() / results.times.len() as f64;

        // Lower variance means better adaptability
        results.adaptability_score = 1.0 / (1.0 + variance.sqrt());
    }

    results
}

#[derive(Debug)]
pub struct BenchmarkResults {
    pub times: Vec<f64>,
    pub correctness: Vec<bool>,
    pub adaptability_score: f64,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_sort() {
        let mut arr = vec![3, 1, 4, 1, 5, 9, 2, 6];
        adaptive_sort(&mut arr);
        assert_eq!(arr, vec![1, 1, 2, 3, 4, 5, 6, 9]);
    }

    #[test]
    fn test_empty_array() {
        let mut arr: Vec<i32> = vec![];
        adaptive_sort(&mut arr);
        assert_eq!(arr, vec![]);
    }

    #[test]
    fn test_single_element() {
        let mut arr = vec![42];
        adaptive_sort(&mut arr);
        assert_eq!(arr, vec![42]);
    }
}
